-- Chunk 3/5
BEGIN;

UPDATE tools SET long_description = E'Buffer, c''est planification de posts sur tous les réseaux. Simple, propre, efficace. À partir de 5.2€/mois. Particulièrement pertinent pour les community-manager et les créateurs de contenu.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : planification multi-plateformes simple sans reporting client. À éviter si : later ou Hootsuite déjà en place — doublon. Free tier suffisant pour moins de 3 canaux.', long_description_en = E'Buffer is schedule posts across all social networks. Simple, clean, effective. Starting at €5.2/month. Most relevant for community-manager and content creators.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'buffer';
UPDATE tools SET long_description = E'Front, c''est hub de communication client pour les équipes. À partir de 15€/mois. Particulièrement pertinent pour les consultants B2B et les fondateurs SaaS.\n\nCe qui distingue Front : spécialisé en shared inbox, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 15€/mois.', long_description_en = E'Front is customer communication hub for teams. Starting at €15/month. Most relevant for B2B consultants and SaaS founders.\n\nWhat sets Front apart: specialized in shared inbox, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified depending on usage. As soon as the tool saves you more than €15/month.' WHERE slug = 'front';
UPDATE tools SET long_description = E'Workday, c''est hCM et finance cloud pour grandes entreprises. À partir de 99€/mois.\n\nCe qui distingue Workday : plateforme RH la plus complète du marché. Ajoutez à ça analytics et reporting avancés, et gestion des talents et performance. Pour les usages intensifs : architecture cloud native. Cas d''usage typique : centraliser toute la gestion RH. On l''utilise aussi pour analyser la performance et les talents.\n\nÀ garder si : organisation 200+ personnes ou besoin d''analytics RH avancés. À éviter si : pME < 50 personnes ou freelance. Point de friction : prix très élevé (enterprise). Réservé aux organisations de 200+ personnes avec un budget RH structuré.', long_description_en = E'Workday is cloud HCM and finance for large enterprises. Starting at €99/month.' WHERE slug = 'workday';
UPDATE tools SET long_description = E'Jira, c''est la référence de la gestion de projet Agile pour équipes tech. À partir de 6.71€/mois. Particulièrement pertinent pour les cto-lead-tech et les product-manager.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : équipe tech établie avec workflows Jira complexes. À éviter si : < 10 personnes — Linear beaucoup plus agréable. Free tier jusqu''à 10 users — pertinent pour débuter. Si le budget le permet, linear est souvent une meilleure option.', long_description_en = E'Jira is the reference agile project management for tech teams. Starting at €6.71/month. Most relevant for cto-lead-tech and product-manager.\n\nEstimated time saving: 4h/month with regular use.\n\nIf budget allows, linear is often a better fit.' WHERE slug = 'jira';
UPDATE tools SET long_description = E'Ownr, c''est plateforme d’enregistrement et de création d’entreprises (Canada). La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les consultants B2B et les daf-finance.\n\nCe qui distingue Ownr : spécialisé en business formation, et interface professionnelle. Gain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Gratuit, à garder si utile.', long_description_en = E'Ownr is business registration and incorporation platform (Canada). Core features are free, with paid plans for advanced use. Most relevant for B2B consultants and daf-finance.\n\nWhat sets Ownr apart: specialized in business formation, and professional interface. Estimated time saving: 2h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: pricing to be verified depending on usage. Free, keep if useful.' WHERE slug = 'ownr';
UPDATE tools SET long_description = E'SignRequest, c''est signature électronique simple et rapide. À partir de 7€/mois.\n\nCe qui distingue SignRequest : interface très simple. Ajoutez à ça prix compétitif, et aPI disponible. Pour les usages intensifs : intégration Box native. Cas d''usage typique : signer des contrats de prestation. On l''utilise aussi pour faire signer des devis clients.\n\nÀ garder si : volume modéré de signatures (5-20/mois) ou budget limité. À éviter si : volume élevé de signatures ou besoin de signature qualifiée eIDAS. Point de friction : fonctionnalités limitées vs DocuSign. Économique dès 3+ signatures par mois vs envoyer des PDF manuellement.', long_description_en = E'SignRequest is simple and fast electronic signature. Starting at €7/month.' WHERE slug = 'signrequest';
UPDATE tools SET long_description = E'Sprout Social, c''est gestion réseaux sociaux premium avec CRM social et analytics avancés. À partir de 215.64€/mois. Particulièrement pertinent pour les community-manager et les manager-dsi.\n\nGain de temps estimé : 7h/mois pour un usage régulier.\n\nÀ garder si : grandes marques avec gestion de crise et CRM social. À éviter si : freelance ou petite agence — Hootsuite ou Buffer suffisent. Pertinent uniquement pour les équipes marketing 5+. Alternative gratuite à considérer : buffer.', long_description_en = E'Sprout Social is premium social media management with social CRM and advanced analytics. Starting at €215.64/month. Most relevant for community-manager and manager-dsi.\n\nEstimated time saving: 7h/month with regular use.\n\nFree alternative worth considering: buffer.' WHERE slug = 'sprout-social';
UPDATE tools SET long_description = E'Packhelp, c''est marketplace de packagings personnalisés. À partir de 10€/mois. Particulièrement pertinent pour les fondateurs SaaS et les developpeur-solo.\n\nCe qui distingue Packhelp : spécialisé en custom packaging, et interface professionnelle. Gain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 10€/mois.', long_description_en = E'Packhelp is marketplace for custom packaging. Starting at €10/month. Most relevant for SaaS founders and solo developers.\n\nWhat sets Packhelp apart: specialized in custom packaging, and professional interface. Estimated time saving: 5h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: prices to be verified according to usage. As soon as the tool saves you more than €10/month.' WHERE slug = 'packhelp';
UPDATE tools SET long_description = E'Silae, c''est logiciel de paie et gestion sociale française. À partir de 35€/mois.\n\nCe qui distingue Silae : référence du marché français de la paie. Ajoutez à ça gestion complète des conventions collectives, et dSN automatisée et conforme. Pour les usages intensifs : écosystème d''intégrations comptables. Cas d''usage typique : éditer les bulletins de paie conformes. On l''utilise aussi pour générer la DSN mensuelle.\n\nÀ garder si : entreprise française avec 5+ salariés ou conventions collectives complexes. À éviter si : freelance sans salarié ou micro-entreprise. Point de friction : interface datée par rapport aux nouveaux entrants. Indispensable dès le premier salarié en CDI si votre comptable le recommande.', long_description_en = E'Silae is french payroll and social management software. Starting at €35/month.' WHERE slug = 'silae';
UPDATE tools SET long_description = E'Typefully, c''est rédaction et planification de threads Twitter/X et posts LinkedIn sans distraction. À partir de 10.39€/mois. Particulièrement pertinent pour les newslettiste-auteur et les consultants B2B.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : actif sur Twitter/X ou LinkedIn avec stratégie éditoriale. À éviter si : buffer ou Later déjà en place pour le social global. Free tier Twitter suffisant pour débuter.', long_description_en = E'Typefully is distraction-free Twitter/X threads and LinkedIn post writing and scheduling. Starting at €10.39/month. Most relevant for newslettiste-auteur and B2B consultants.\n\nEstimated time saving: 3h/month with regular use.' WHERE slug = 'typefully';
