UPDATE tools SET long_description = E'Kajabi, c''est la plateforme tout-en-un pour créateurs : cours, communauté, email, paiements. À partir de 47.63€/mois. Particulièrement pertinent pour les coach-formateur et les créateurs de contenu.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : formateur avec cours + communauté + email en un. À éviter si : teachable + Mailchimp déjà en place — doublon formation. Rentable dès 3 000€/mois de revenus formation.', long_description_en = E'Kajabi is the all-in-one platform for creators: courses, community, email, payments. Starting at €47.63/month. Most relevant for coach-formateur and content creators.\n\nEstimated time saving: 5h/month with regular use.' WHERE slug = 'kajabi';
