UPDATE tools SET long_description = E'Bloom, c''est cRM et portail client pour créatifs et photographes. À partir de 13€/mois.\n\nCe qui distingue Bloom : conçu spécifiquement pour les créatifs. Ajoutez à ça galeries clients intégrées, et prix accessible. Pour les usages intensifs : interface propre et moderne. Cas d''usage typique : envoyer des propositions à des clients potentiels. On l''utilise aussi pour partager des galeries photos avec les clients.\n\nÀ garder si : photographe ou vidéaste freelance ou besoin de galeries clients. À éviter si : consultant non-créatif ou besoin d''un CRM complet. Point de friction : fonctionnalités limitées vs HoneyBook. Bon choix pour les créatifs visuels avec 2-10 clients actifs.', long_description_en = E'Bloom is cRM and client portal for creatives and photographers. Starting at €13/month.' WHERE slug = 'bloom-crm';
