UPDATE tools SET long_description = E'Legifrance Pro, c''est accès aux textes juridiques français officiels. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue Legifrance Pro : gratuit et officiel. Ajoutez à ça base de données juridique exhaustive, et mise à jour en temps réel. Pour les usages intensifs : recherche avancée par thème et date. Cas d''usage typique : vérifier une clause contractuelle. On l''utilise aussi pour rechercher une convention collective.\n\nÀ garder si : besoin de vérifier des textes de loi ou veille juridique régulière. À éviter si : besoin de conseil juridique personnalisé ou aucune connaissance juridique. Point de friction : interface austère et technique. Gratuit — à bookmarker pour toute vérification juridique ponctuelle.', long_description_en = E'Legifrance Pro is access to official French legal texts. Core features are free, with paid plans for advanced use.' WHERE slug = 'legifrance-pro';
