UPDATE tools SET long_description = E'Nusii, c''est logiciel de propositions commerciales pour agences. À partir de 29€/mois.\n\nCe qui distingue Nusii : interface épurée et rapide. Ajoutez à ça focus sur l''essentiel (pas de bloat), et notifications en temps réel. Pour les usages intensifs : templates réutilisables. Cas d''usage typique : rédiger des propositions rapidement. On l''utilise aussi pour suivre les propositions envoyées.\n\nÀ garder si : besoin d''un outil simple pour les propositions ou agence ou consultant. À éviter si : besoin de signature intégrée ou fonctionnalités avancées requises. Point de friction : moins de fonctionnalités que Proposify. Bon choix pour les agences qui veulent un outil sans complexité.', long_description_en = E'Nusii is commercial proposal software for agencies. Starting at €29/month.' WHERE slug = 'nusii';
