UPDATE tools SET long_description = E'Waalaxy, c''est prospection LinkedIn automatisée. À partir de 40€/mois.\n\nCe qui distingue Waalaxy : interface intuitive (pas besoin d''être technique). Ajoutez à ça cRM de prospection intégré, et séquences LinkedIn + Email. Pour les usages intensifs : communauté française active. Cas d''usage typique : automatiser les demandes de connexion LinkedIn. On l''utilise aussi pour envoyer des séquences de messages personnalisés.\n\nÀ garder si : prospection LinkedIn active ou besoin d''un outil simple sans courbe d''apprentissage. À éviter si : pas de prospection LinkedIn ou besoin d''outreach email avancé. Point de friction : limité à LinkedIn principalement. Utile dès 20+ connexions LinkedIn par semaine.', long_description_en = E'Waalaxy is automated LinkedIn prospecting. Starting at €40/month.' WHERE slug = 'waalaxy';
