UPDATE tools SET long_description = E'HeyGen, c''est création de vidéos avec avatars IA et traduction automatique. À partir de 25.11€/mois. Particulièrement pertinent pour les créateurs de contenu et les coach-formateur.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : vidéos explicatives ou cours sans apparaître à la caméra. À éviter si : contenu authentique — un vrai visage reste plus engageant. Rentable dès 4 vidéos d''avatars par mois.', long_description_en = E'HeyGen is video creation with AI avatars and automatic translation. Starting at €25.11/month. Most relevant for content creators and coach-formateur.\n\nEstimated time saving: 5h/month with regular use.\n\nKeep it if: explainer videos or courses without appearing on camera. Skip it if: authentic content — a real face remains more engaging. Profitable starting from 4 avatar videos per month.' WHERE slug = 'heygen';
